def decode(u, n):
    return u - (1 << n) if u & (1 << (n - 1)) else u

print(decode(0x800, 12), decode(0x7FF, 12))

def apparent(f, fs):
    return abs(f - round(f / fs) * fs)

print(apparent(35, 50), apparent(260, 100))

def crc16(data):
    crc = 0xFFFF
    for byte in data:
        crc ^= byte << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) if crc & 0x8000 else crc << 1
            crc &= 0xFFFF
    return crc

